#pragma once
// Minimal assert-based test harness used by all test_*.cpp files.
//
// Usage:
//   DSL_TEST(my_feature) {
//       DSL_REQUIRE(2 + 2 == 4);
//   }
//   int main() { return ::dsl::testing::runAll(); }

#include <cstdio>
#include <functional>
#include <sstream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

namespace dsl {
namespace testing {

struct TestCase {
    std::string name;
    std::function<void()> fn;
};

inline std::vector<TestCase>& registry() {
    static std::vector<TestCase> instance;
    return instance;
}

struct Registrar {
    Registrar(std::string name, std::function<void()> fn) {
        registry().push_back({std::move(name), std::move(fn)});
    }
};

inline int runAll() {
    int failures = 0;
    for (const TestCase& tc : registry()) {
        std::printf("[ RUN  ] %s\n", tc.name.c_str());
        try {
            tc.fn();
            std::printf("[  OK  ] %s\n", tc.name.c_str());
        } catch (const std::exception& e) {
            ++failures;
            std::printf("[ FAIL ] %s: %s\n", tc.name.c_str(), e.what());
        }
    }
    std::printf("%zu test(s), %d failure(s)\n", registry().size(), failures);
    return failures == 0 ? 0 : 1;
}

}  // namespace testing
}  // namespace dsl

// REQUIRE throws instead of assert() so checks survive Release builds
// (where NDEBUG would silently disable assert()).
#define DSL_REQUIRE(cond)                                                          \
    do {                                                                           \
        if (!(cond)) {                                                             \
            std::ostringstream dsl_oss;                                            \
            dsl_oss << __FILE__ << ":" << __LINE__ << "  requirement failed: " #cond; \
            throw std::runtime_error(dsl_oss.str());                               \
        }                                                                          \
    } while (false)

#define DSL_TEST(name)                                                        \
    static void dsl_test_##name##_impl();                                     \
    static const ::dsl::testing::Registrar dsl_test_##name##_reg{             \
        #name, dsl_test_##name##_impl};                                       \
    static void dsl_test_##name##_impl()

#include "test_main.hpp"

#include <stdexcept>
#include <vector>

// TODO(project): replace this std::vector stand-in with dsl::DynamicArray<T>
// once include/dsl/dynamic_array.hpp exists. The tests should not change.
template <typename T>
using DynamicArray = std::vector<T>;

DSL_TEST(push_back_and_index) {
    DynamicArray<int> a;
    DSL_REQUIRE(a.size() == 0);
    for (int i = 0; i < 1000; ++i) {
        a.push_back(i);
    }
    DSL_REQUIRE(a.size() == 1000);
    DSL_REQUIRE(a[0] == 0);
    DSL_REQUIRE(a[999] == 999);
}

DSL_TEST(out_of_range_throws) {
    DynamicArray<int> a;
    a.push_back(1);
    bool threw = false;
    try {
        (void)a.at(5);
    } catch (const std::out_of_range&) {
        threw = true;
    }
    DSL_REQUIRE(threw);
}

int main() { return ::dsl::testing::runAll(); }
